    + `<polyline transform="translate(20 10)" points="${points}" fill="none" stroke="#c5273c" stroke-width="5" stroke-linejoin="round" stroke-linecap="round" pathLength="1" stroke-dasharray="${progress} 1"/>`
    + y2026Text(485, 145, 'Путь через коридоры', 19)
