const y2026LinePath = [[0,1],[1,1],[1,2],[2,2],[2,1],[2,0],[3,0],[3,1],[3,2],[3,3],[4,3],[4,2],[4,1]];
function y2026LineScene(step, frame) {
  const x = c => 176 + c * 72;
  const y = r => 60 + r * 58;
  let out = '';
  for (let c = 0; c < 5; c++) out += `<path d="M${x(c)} 45v204" stroke="#a4afb1"/>`;
  for (let r = 0; r < 4; r++) out += `<path d="M158 ${y(r)}h324" stroke="#a4afb1"/>`;
  const points = y2026LinePath.map(([c,r]) => `${x(c)},${y(r)}`).join(' ');
  out += `<polyline points="${points}" fill="none" stroke="#168163" stroke-width="5"/>`;
  const revealed = step === 1 ? 0 : step === 2 ? 12 * y2026Progress(frame, 4) : 12;
  y2026LinePath.forEach(([c,r], index) => {
    const opacity = index === 12 || index === 0 ? 1 : Math.max(0, Math.min(1, revealed - index + 1));
    if (index !== 7 || step >= 3) {
      out += `<g opacity="${opacity}"><circle cx="${x(c)}" cy="${y(r)}" r="5" fill="#168163"/>`;
      out += y2026Text(x(c) + (index === 3 || index === 4 ? -14 : 15), y(r) - 8, index, 18) + '</g>';
    }
  });
  if (step < 3) out += y2026Text(x(3) + 14, y(1) - 8, '★', 23);
  out += y2026Caption(step === 1 ? '12 равных промежутков' : step === 2 ? 'Одна сторона клетки — один шаг' : 'Звёздочка на шаге 7');
  return svg(out, 'Ломаная из двенадцати шагов, звезда на седьмом');
}

function y2026PencilScene(step) {
  const lengths = [153, 124, 178, 124, 100];
  let out = y2026Title(step === 1 ? 'Найди самый короткий' : step === 2 ? 'Сравни Б и Г' : 'А короче В');
  lengths.forEach((length, i) => {
    const name = y2026Letters[i];
    const x = 132 + i * 94;
    const top = 229 - length;
    const same = (i === 1 || i === 3) && step >= 2;
    const color = (i === 4 || step === 3) ? y2026LettersToColors[name] : null;
    out += `<path d="M${x-10} 229V${top+28}L${x} ${top}l10 28v${length-28}Z" fill="${color || (same ? y2026Highlight : '#fff')}" stroke="${y2026Ink}" stroke-width="2"/>`
      + `<path d="M${x-10} ${top+28}h20" stroke="${y2026Ink}"/>`
      + y2026Text(x, 260, name);
  });
  if (step >= 2) out += '<path d="M226 97H414" stroke="#14665b" stroke-width="2" stroke-dasharray="5 5"/>';
  return svg(out, 'Высоты карандашей. Б и Г одинаковы, Д короче всех, А короче В');
}

