const y2026RoadBridge = [[7,1],[8,1],[9,1],[9,2],[9,3],[10,3]];
function y2026RoadScene(step, frame) {
  const x = 68;
  const y = 50;
  const unit = 36;
  const placed = y2026Progress(frame);
  let out = y2026Grid(Array.from({length: 6}, () => Array(14).fill('')), {
    x, y, unit,
    fill: (r, c) => y2026RoadExisting.some(([col,row]) => c === col && r === row) ? '#77775b' :
      step <= 2 && c >= 7 && c <= 10 ? '#f9f1d7' : '#fff',
  });
  if (step === 1) {
    for (let i = 0; i < 4; i++) out += y2026Text(x + unit * (7.5 + i), 34, i + 1, 19);
  } else if (step === 2) {
    out += y2026Text(x + 7.5 * unit, y + 1.7 * unit, '←', 27, y2026Accent)
      + y2026Text(x + 10.5 * unit, y + 3.7 * unit, '→', 27, y2026Accent);
  } else {
    out += `<g opacity="${placed}" transform="translate(0 ${-28 * (1 - placed)})">`
      + y2026RoadBridge.map(([c,r]) => y2026Rect(x + unit * c, y + unit * r, unit, unit, '#e68a46')).join('') + '</g>';
  }
  return svg(out, 'Недостроенная дорога и четырёхклеточный промежуток по ширине');
}

