function y2026PaperScene(step, frame) {
  const panels = [
    {x: 129, label: 'Серый', color: '#9ea2a5', sides: [4, 0, 0, 4], count: '1 квадрат'},
    {x: 320, label: 'Белый', color: '#fff', sides: [4, 1, 1, 4], count: '2 квадрата'},
    {x: 511, label: 'Чёрный', color: '#374243', sides: [1.5, 1, 1, 1.5], count: '2 квадрата'},
  ];
  const unit = 25;
  let out = '';
  panels.forEach(({x,label,color,sides,count}, index) => {
    if (step === 1 && index) return;
    const [left,right,top,bottom] = sides;
    const center = x + (left-right) * unit / 2;
    const cut = index ? 102 : 78;
    const separ = index ? y2026Progress(frame) * 5 : 0;
    out += y2026Text(x, 38, label);
    [top,bottom].forEach((height,r) => [left,right].forEach((width,c) => {
      if (!height || !width) return;
      const square = width === height;
      const px = center + (c ? separ : -width * unit - separ);
      const py = cut + (r ? separ : -height * unit - separ);
      out += y2026Rect(px, py, width * unit, height * unit, color);
      if (square) out += y2026Text(px + width * unit / 2, py + height * unit / 2 + 8, '✓', 20, index === 2 ? '#d5eee4' : y2026Accent);
    }));
    out += y2026Text(x, 236, count, 19, y2026Accent);
  });
  if (step === 3) out += y2026Caption('1 + 2 + 2 = 5');
  return svg(out, 'Квадратные части белого, серого и чёрного слоёв');
}

