const y2026ButtonStart = [1,0,1,0];
const y2026ButtonPresses = [1,2,3];
const y2026ButtonPress = (state, button) => state.map((shape,index) => Number(Math.abs(index-button) <= 1) ^ shape);
function y2026ButtonScene(step, frame) {
  const progress = step === 3 ? 3 * y2026Progress(frame,3.8) : 0;
  const completed = Math.floor(progress);
  const phase = progress - completed;
  const before = y2026ButtonPresses.slice(0,completed).reduce(y2026ButtonPress,y2026ButtonStart);
  const nextPress = y2026ButtonPresses[completed];
  const circle = x => `<circle cx="${x}" cy="138" r="33" fill="#62a980" stroke="#17493c" stroke-width="2"/>`;
  const triangle = x => `<path d="M${x} 104l38 67h-76Z" fill="#62a980" stroke="#17493c" stroke-width="2"/>`;
  let out = '';
  before.forEach((shape,index) => {
    const x = 125 + index*130;
    if ((step === 1 && index === 2) || (step === 2 && index >= 2) || (step === 3 && completed < 3 && index === nextPress)) {
      out += y2026Rect(x-54,79,108,124,y2026Highlight,'none',12);
    }
    const affected = step === 3 && completed < 3 && Math.abs(index-nextPress) <= 1;
    const first = shape ? triangle(x) : circle(x);
    const second = shape ? circle(x) : triangle(x);
    out += affected ? `<g opacity="${1-phase}">${first}</g><g opacity="${phase}">${second}</g>` : first;
    out += y2026Text(x,70,index+1);
  });
  return svg(out + y2026Caption(step === 1 ? 'Кнопка 3 обязательна' : step === 2 ? 'Нужны 3, 4 и одна кнопка слева' : 'Нажимаем 2 → 3 → 4',253),
    'Уникальная тройка кнопок для четырёх кругов: вторая, третья и четвёртая');
}

